def image_generation(image_prompt, width=None, height=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0404000" if __import__("os").path.isdir("./environment_mix/0404000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # Minimal request logging even though no explicit log collection is declared.
    def _log(status, client_id=None, details=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "reqlog_" + uuid.uuid4().hex,
                "endpoint": "image_generation",
                "client_id": client_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now.isoformat(),
                "details": details or {}
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs
    if not isinstance(image_prompt, str) or len(image_prompt.strip()) == 0:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "image_prompt must be a non-empty string.")
    prompt = image_prompt.strip()
    if len(prompt) < 1 or len(prompt) > 4000:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "image_prompt length must be between 1 and 4000 characters.")

    if width is None:
        width = 1024
    if height is None:
        height = 1024
    if not isinstance(width, int) or not isinstance(height, int):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "width and height must be integers.")
    if not (64 <= width <= 4096) or not (64 <= height <= 4096) or (width % 8 != 0) or (height % 8 != 0):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "width and height must be in [64,4096] and divisible by 8.",
                    error_code="invalid_dimensions")

    # Authenticate ambiently: pick an active client that can serve the call.
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        _log("error", None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active API client is available for this request.")
    # Choose a client that has non-negative quotas (schema constraints) and is able to accept at least 1 request.
    def _qint(v):
        try:
            return int(v)
        except Exception:
            return None
    chosen = None
    for c in active_clients:
        qr = _qint(c.get("quota_requests_per_day"))
        qp = _qint(c.get("quota_pixels_per_day"))
        if qr is None or qp is None or qr < 0 or qp < 0:
            continue
        chosen = c
        break
    if not chosen:
        _log("error", None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No eligible API client is available for this request.")
    client_id = chosen.get("id")

    # Enforce quotas: usage_daily per (client_id, today_utc)
    usage = _load("usage_daily.json")
    if not isinstance(usage, list):
        usage = []
    day = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
    day_iso = day.isoformat()
    usage_row = None
    for r in usage:
        if isinstance(r, dict) and r.get("client_id") == client_id and r.get("usage_date") == day_iso:
            usage_row = r
            break

    reqs_used = int(usage_row.get("requests_count", 0)) if usage_row else 0
    px_used = int(usage_row.get("pixels_count", 0)) if usage_row else 0
    px_add = width * height

    quota_r = int(chosen.get("quota_requests_per_day", 0))
    quota_p = int(chosen.get("quota_pixels_per_day", 0))

    # If quota is 0, no requests allowed.
    if reqs_used + 1 > quota_r or px_used + px_add > quota_p:
        _log("error", client_id, {"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", error_code="quota_exceeded",
                    quota_requests_per_day=quota_r, quota_pixels_per_day=quota_p,
                    requests_used=reqs_used, pixels_used=px_used)

    # Idempotency: tool has no idempotency_key parameter; support via _extra if provided.
    idempotency_key = _extra.get("idempotency_key", None)
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")

    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []
    if idempotency_key:
        for r in gen_reqs:
            if isinstance(r, dict) and r.get("client_id") == client_id and r.get("idempotency_key") == idempotency_key:
                # Return existing request result without incrementing usage.
                rid = r.get("id")
                assets = _load("image_assets.json")
                if not isinstance(assets, list):
                    assets = []
                urls = []
                if r.get("status") == "succeeded":
                    for a in assets:
                        if isinstance(a, dict) and a.get("request_id") == rid and a.get("status") == "available":
                            pu = a.get("public_url")
                            if isinstance(pu, str) and pu:
                                urls.append(pu)
                body = {
                    "request": r,
                    "image_urls": urls
                }
                _log("ok", client_id, {"idempotent_replay": True, "request_id": rid})
                return body

    # Accept request: create generation_requests row
    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    created_at = now.isoformat()
    req_id = _new_id("genreq")
    # Ensure uniqueness
    existing_ids = {r.get("id") for r in gen_reqs if isinstance(r, dict)}
    while req_id in existing_ids:
        req_id = _new_id("genreq")

    # Detect prompt language: tool requires English; mark unknown if non-ascii heavy.
    ascii_ratio = sum(1 for ch in prompt if ord(ch) < 128) / max(1, len(prompt))
    prompt_language = "en" if ascii_ratio > 0.9 else "unknown"

    req_row = {
        "id": req_id,
        "client_id": client_id,
        "image_prompt": prompt,
        "width": width,
        "height": height,
        "prompt_language": prompt_language,
        "expanded_prompt_en": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "source_ip": _extra.get("source_ip") if isinstance(_extra.get("source_ip", None), str) else None,
        "idempotency_key": idempotency_key,
        "requested_at": created_at,
        "started_at": None,
        "finished_at": None,
        "created_at": created_at,
        "updated_at": created_at
    }

    # Enforce unique(client_id, idempotency_key) where idempotency_key not null
    if idempotency_key:
        for r in gen_reqs:
            if isinstance(r, dict) and r.get("client_id") == client_id and r.get("idempotency_key") == idempotency_key:
                # Another concurrent write may have created it; return that.
                rid = r.get("id")
                _log("ok", client_id, {"idempotent_replay": True, "request_id": rid})
                return {"request": r, "image_urls": []}

    # Persist request and usage update atomically-ish (best effort)
    gen_reqs.append(req_row)
    _save("generation_requests.json", gen_reqs)

    if usage_row is None:
        usage_row = {
            "id": _new_id("usage"),
            "client_id": client_id,
            "usage_date": day_iso,
            "requests_count": 0,
            "pixels_count": 0,
            "created_at": created_at,
            "updated_at": created_at
        }
        usage.append(usage_row)

    usage_row["requests_count"] = int(usage_row.get("requests_count", 0)) + 1
    usage_row["pixels_count"] = int(usage_row.get("pixels_count", 0)) + px_add
    usage_row["updated_at"] = created_at
    _save("usage_daily.json", usage)

    # Update api client last_used_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = created_at
            c["updated_at"] = created_at
            break
    _save("api_clients.json", clients)

    _log("ok", client_id, {"request_id": req_id})
    return {
        "request": req_row,
        "image_urls": []
    }

def list_generation_requests(status=None, idempotency_key=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0404000" if __import__("os").path.isdir("./environment_mix/0404000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _log(status_s, client_id=None, details=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "reqlog_" + uuid.uuid4().hex,
                "endpoint": "list_generation_requests",
                "client_id": client_id,
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now.isoformat(),
                "details": details or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate filters
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", None, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a string.")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            d = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(field)

    try:
        ca = _parse_dt(created_after, "created_after")
        cb = _parse_dt(created_before, "created_before")
    except ValueError as e:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", f"Invalid date-time for {str(e)} (expected ISO 8601).")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    # Authenticate ambiently
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        _log("error", None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active API client is available for this request.")
    client_id = active_clients[0].get("id")

    # Pagination cursor is an opaque created_at|id marker
    cursor_dt = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or "|" not in cursor:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        a, b = cursor.split("|", 1)
        try:
            cursor_dt = datetime.datetime.fromisoformat(a.replace("Z", "+00:00"))
            if cursor_dt.tzinfo is None:
                cursor_dt = cursor_dt.replace(tzinfo=datetime.timezone.utc)
            cursor_dt = cursor_dt.astimezone(datetime.timezone.utc)
        except Exception:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        cursor_id = b

    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []

    def _dt(row):
        v = row.get("created_at")
        if not isinstance(v, str):
            return None
        try:
            d = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    rows = []
    for r in gen_reqs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if idempotency_key is not None and r.get("idempotency_key") != idempotency_key:
            continue
        d = _dt(r)
        if ca is not None and (d is None or d < ca):
            continue
        if cb is not None and (d is None or d >= cb):
            continue
        if cursor_dt is not None:
            # newest first: skip anything >= cursor marker (already seen)
            if d is None:
                continue
            rid = r.get("id")
            if d > cursor_dt:
                continue
            if d == cursor_dt and isinstance(rid, str) and isinstance(cursor_id, str) and rid >= cursor_id:
                continue
        rows.append(r)

    # Sort newest first by created_at then id
    def _sort_key(r):
        d = _dt(r)
        # None goes last
        if d is None:
            d = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        rid = r.get("id")
        if not isinstance(rid, str):
            rid = ""
        return (d, rid)

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _dt(last)
        last_id = last.get("id") if isinstance(last.get("id"), str) else ""
        if last_dt is not None:
            next_cursor = f"{last_dt.isoformat()}|{last_id}"

    _log("ok", client_id, {"returned": len(page), "has_more": has_more})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_generation_request(id, include_assets=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0404000" if __import__("os").path.isdir("./environment_mix/0404000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, client_id=None, code=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "reqlog_" + uuid.uuid4().hex,
            "endpoint": "get_generation_request",
            "client_id": client_id,
            "status": status_s,
            "code": code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "details": details or {}
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log("error", None, "VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    if include_assets is None:
        include_assets = False
    if not isinstance(include_assets, bool):
        _log("error", None, "VALIDATION_ERROR", {"field": "include_assets"})
        return _err("VALIDATION_ERROR", "include_assets must be a boolean.", field="include_assets")

    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []

    req = None
    for r in gen_reqs:
        if isinstance(r, dict) and r.get("id") == id:
            req = r
            break

    if req is None:
        _log("error", None, "NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Generation request not found.")

    # Ambient auth: signature has no credential, so do NOT reject due to "missing/invalid API key".
    # Ownership is inferred from the request row itself; "deleted" clients still own historical data.
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    owner_id = req.get("client_id")
    owner = None
    if isinstance(owner_id, str) and owner_id:
        for c in clients:
            if isinstance(c, dict) and c.get("id") == owner_id:
                owner = c
                break
    if owner is None:
        # If the client row truly doesn't exist, treat as not found to avoid leaking ids
        _log("error", owner_id, "NOT_FOUND", {"id": id, "reason": "owner_missing"})
        return _err("NOT_FOUND", "Generation request not found.")

    out = dict(req)

    if include_assets:
        assets = _load("image_assets.json")
        if not isinstance(assets, list):
            assets = []
        req_assets = []
        for a in assets:
            if isinstance(a, dict) and a.get("request_id") == id:
                req_assets.append(dict(a))
        out["assets"] = req_assets

    _log("ok", owner_id, None, {"include_assets": include_assets})
    return {"generation_request": out}

def cancel_generation_request(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0404000" if __import__("os").path.isdir("./environment_mix/0404000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, client_id=None, code=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "reqlog_" + uuid.uuid4().hex,
            "endpoint": "cancel_generation_request",
            "client_id": client_id,
            "status": status_s,
            "code": code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "details": details or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _log("error", None, "VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []

    idx = None
    req = None
    for i, r in enumerate(gen_reqs):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            req = r
            break

    if req is None:
        _log("error", None, "NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Generation request not found.")

    # Ambient auth: no credential param, so infer ownership from request row.
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    owner_id = req.get("client_id")
    owner = None
    if isinstance(owner_id, str) and owner_id:
        for c in clients:
            if isinstance(c, dict) and c.get("id") == owner_id:
                owner = c
                break
    if owner is None:
        _log("error", owner_id, "NOT_FOUND", {"id": id, "reason": "owner_missing"})
        return _err("NOT_FOUND", "Generation request not found.")

    status = req.get("status")
    if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _log("error", owner_id, "CONFLICT", {"id": id, "reason": "unknown_status", "status": status})
        return _err("CONFLICT", "Generation request is in an unknown state and cannot be cancelled.", status=status)

    # Lifecycle: only queued/running -> cancelled allowed. Terminals refuse with CONFLICT.
    if status in ("succeeded", "failed", "cancelled"):
        _log("error", owner_id, "CONFLICT", {"id": id, "status": status})
        return _err("CONFLICT", "Generation request is already terminal and cannot be cancelled.", status=status)

    # Transition queued/running -> cancelled
    updated = dict(req)
    updated["status"] = "cancelled"
    updated["finished_at"] = now_iso
    updated["updated_at"] = now_iso
    if not updated.get("started_at") and status == "running":
        updated["started_at"] = now_iso  # best-effort consistency

    gen_reqs[idx] = updated
    _save("generation_requests.json", gen_reqs)

    _log("ok", owner_id, None, {"from_status": status, "to_status": "cancelled"})
    return {"generation_request": updated}

def list_image_assets(request_id=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0404000" if __import__("os").path.isdir("./environment_mix/0404000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Ambient authentication resolution (must find an active client that can serve reads) ---
    clients = _load("api_clients.json")
    authed_client = None
    for c in clients:
        if c.get("status") == "active":
            authed_client = c
            break
    # Record call in audit/usage collection if present; spec says usage/audit must be recorded on EVERY call.
    # Only usage_daily exists; we will append a non-counter "audit style" row only when schema has one.
    # Since it doesn't, we will still update client last_used_at on successful authenticated requests.
    if authed_client is None:
        return _err("UNAUTHORIZED", "API key missing/invalid (no active client context available).")

    # --- Validate inputs ---
    if request_id is not None and not isinstance(request_id, str):
        return _err("VALIDATION_ERROR", "request_id must be a string.")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("creating", "available", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: creating, available, deleted.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # --- Load data ---
    assets = _load("image_assets.json")
    reqs = _load("generation_requests.json")

    # Build request lookup and enforce ownership via generation_requests.client_id
    req_by_id = {r.get("id"): r for r in reqs if isinstance(r, dict)}

    if request_id is not None:
        r = req_by_id.get(request_id)
        if r is None or r.get("client_id") != authed_client.get("id"):
            # For list, returning empty is acceptable for non-matching filters;
            # but tool description implies auth-based ownership. We keep it empty, not error.
            filtered = []
        else:
            filtered = [a for a in assets if isinstance(a, dict) and a.get("request_id") == request_id]
    else:
        # All assets whose request belongs to client
        filtered = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            rid = a.get("request_id")
            r = req_by_id.get(rid)
            if r is not None and r.get("client_id") == authed_client.get("id"):
                filtered.append(a)

    if status is not None:
        filtered = [a for a in filtered if a.get("status") == status]

    # Sort deterministically by created_at then id
    def _key(a):
        ca = a.get("created_at") or ""
        return (ca, a.get("id") or "")
    filtered.sort(key=_key)

    # Cursor handling: opaque base64 of last seen id
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            # raw format: "id:<asset_id>"
            if raw.startswith("id:"):
                last_id = raw[3:]
                # find first item strictly after last_id in the current sorted list, comparing by id within same ordering
                # We'll advance by scanning for exact id match then start after it.
                for i, a in enumerate(filtered):
                    if a.get("id") == last_id:
                        start = i + 1
                        break
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = filtered[start:start + limit]
    has_more = (start + limit) < len(filtered)
    next_cursor = None
    if has_more and page:
        next_cursor = base64.urlsafe_b64encode(("id:" + str(page[-1].get("id"))).encode("utf-8")).decode("utf-8").rstrip("=")

    # Update last_used_at for successful authenticated call
    authed_client["last_used_at"] = now
    authed_client["updated_at"] = now
    # persist the client update
    for i, c in enumerate(clients):
        if c.get("id") == authed_client.get("id"):
            clients[i] = authed_client
            break
    _save("api_clients.json", clients)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
            "latency_ms": latency_ms,
            "timestamp": now
        }
    }

def get_image_asset(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0404000" if __import__("os").path.isdir("./environment_mix/0404000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, client_id=None, code=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "reqlog_" + uuid.uuid4().hex,
            "endpoint": "get_image_asset",
            "client_id": client_id,
            "status": status_s,
            "code": code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "details": details or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _log("error", None, "VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    assets = _load("image_assets.json")
    if not isinstance(assets, list):
        assets = []

    asset = None
    for a in assets:
        if isinstance(a, dict) and a.get("id") == id:
            asset = a
            break
    if asset is None:
        _log("error", None, "NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Image asset not found.")

    # Resolve parent request (and therefore owner). Deleted clients still can read historical rows.
    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []
    req_id = asset.get("request_id")
    req = None
    if isinstance(req_id, str) and req_id:
        for r in gen_reqs:
            if isinstance(r, dict) and r.get("id") == req_id:
                req = r
                break
    if req is None:
        _log("error", None, "NOT_FOUND", {"id": id, "reason": "parent_request_missing"})
        return _err("NOT_FOUND", "Image asset not found.")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    owner_id = req.get("client_id")
    owner = None
    if isinstance(owner_id, str) and owner_id:
        for c in clients:
            if isinstance(c, dict) and c.get("id") == owner_id:
                owner = c
                break
    if owner is None:
        _log("error", owner_id, "NOT_FOUND", {"id": id, "reason": "owner_missing"})
        return _err("NOT_FOUND", "Image asset not found.")

    _log("ok", owner_id, None, {"request_id": req_id})
    return {"image_asset": dict(asset)}
